import { Resend } from "npm:resend@6.17.2";

const ALERT_RECIPIENT = "dgomez@limpatex.com";
const DEFAULT_FROM = "Sistema Smoobu <alertas@limpatexgestion.es>";

const json = (body: unknown, status = 200) => new Response(JSON.stringify(body), {
  status,
  headers: {
    "Content-Type": "application/json",
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Headers": "authorization, content-type, x-smoobu-alert-token",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
  },
});

const textValue = (value: unknown, maxLength: number): string =>
  typeof value === "string" ? value.trim().slice(0, maxLength) : "";

Deno.serve(async (req: Request): Promise<Response> => {
  if (req.method === "OPTIONS") return json({ ok: true });
  if (req.method !== "POST") return json({ error: "method_not_allowed" }, 405);

  const configuredToken = Deno.env.get("SMOOBU_ALERT_FUNCTION_TOKEN")?.trim() ?? "";
  const receivedToken = req.headers.get("x-smoobu-alert-token")?.trim() ?? "";
  if (!configuredToken || receivedToken !== configuredToken) {
    return json({ error: "unauthorized" }, 401);
  }

  const resendApiKey = Deno.env.get("RESEND_API_KEY")?.trim() ?? "";
  if (!resendApiKey) return json({ error: "resend_not_configured" }, 503);

  let payload: { source?: unknown; subject?: unknown; body?: unknown };
  try {
    payload = await req.json();
  } catch {
    return json({ error: "invalid_json" }, 400);
  }

  if (payload.source !== "smoobu") return json({ error: "invalid_source" }, 400);
  const subject = textValue(payload.subject, 180);
  const body = textValue(payload.body, 20_000);
  if (!subject || !body) return json({ error: "subject_and_body_required" }, 400);

  try {
    const response = await new Resend(resendApiKey).emails.send({
      from: Deno.env.get("SMOOBU_ALERT_FROM")?.trim() || DEFAULT_FROM,
      to: [ALERT_RECIPIENT],
      subject,
      text: body,
    });

    if (response.error) {
      console.error("Smoobu Resend error:", response.error.message ?? "provider_error");
      return json({ error: "resend_error" }, 502);
    }

    const messageId = response.data?.id?.trim();
    if (!messageId) {
      console.error("Smoobu Resend response did not include a message id");
      return json({ error: "resend_missing_message_id" }, 502);
    }

    return json({ status: "sent", id: messageId });
  } catch (error) {
    console.error(
      "Smoobu Resend exception:",
      error instanceof Error ? error.message : "provider_exception",
    );
    return json({ error: "resend_exception" }, 502);
  }
});
